const nextNumber = (prefix, rows, digits=5, start=0) => prefix + String(Math.max(start, ...rows.map(x=> Number(String(x.id).replace(/\D/g,''))||0))+1).padStart(digits,'0');
const loadSeed = () => {
    let stored;
    try {stored=JSON.parse(localStorage.getItem('mlm-franchise-demo-v1'));}catch{}
    const base=stored||clone(seed);
    const hadPurchases=Array.isArray(base.purchases);
    base.purchases=base.purchases||[];
    base.quotations=base.quotations||[];
    base.orders=base.orders||[];
    base.leakage=base.leakage||[];
    base.returns=base.returns||[];
    // Migrate previously received sample orders into demo purchase invoices.
    if(!hadPurchases) base.orders.filter(x=>x.status!=='Ordered').forEach((o,i)=>base.purchases.push({id:'PUR-'+String(i+1).padStart(5,'0'),orderId:o.id,date:o.receivedDate||o.date,companyInvoice:o.companyInvoice||'',items:o.items.map(it=>({productId:it.productId,good:it.good,leakage:it.leakage,price:it.price})),reason:'Previously received stock'}));
    return base;
};
